{"content": "#!/usr/bin/env python3
import json, sys, collections

PAPER = "/home/user/gp-rarelink/data/literature/ha20/fulltext_md/35958611.md"
OUT = "/home/user/gp-rarelink/data/extracted/ha20/ow-ha20/per_paper/35958611.json"
paper = open(PAPER, encoding="utf-8").read()
low = paper.lower()
data = json.load(open(OUT, encoding="utf-8"))

schema = json.load(open("/home/user/gp-rarelink/pipeline/extract/claude_code/schema_ha20_v5.json", encoding="utf-8"))
schema_fields = {t["name"]: [f["name"] for f in t["fields"]] for t in schema["tables"]}

problems = []
def check_span(s, where):
    if s is None:
        return
    if s not in paper:
        if s.lower() in low:
            problems.append("CASE: " + where + " :: " + s[:80])
        else:
            problems.append("MISSING: " + where + " :: " + s[:120])

for tname, rows in data["tables"].items():
    for i, row in enumerate(rows):
        if list(row.keys()) != schema_fields[tname]:
            problems.append("FIELDS %s row %d: %s" % (tname, i, set(row.keys()) ^ set(schema_fields[tname])))
        for fname, c in row.items():
            if not isinstance(c, dict) or set(c.keys()) != {"value", "span"}:
                problems.append("CELL %s row %d %s" % (tname, i, fname)); continue
            v, s = c["value"], c["span"]
            if isinstance(s, list):
                for x in s:
                    check_span(x, "%s[%d].%s" % (tname, i, fname))
            else:
                check_span(s, "%s[%d].%s" % (tname, i, fname))
            if v is not None and s is None:
                if fname in ("hpo_label_candidate", "hpo_id_candidate", "checklist_feature"):
                    continue
                problems.append("NO SPAN: %s[%d].%s = %r" % (tname, i, fname, v))

# labels consistent
ind_labels = [r["individual_label_in_paper"]["value"] for r in data["tables"]["individuals"]]
for tname in ("variants", "phenotypic_features", "phenotype_checklist"):
    for r in data["tables"][tname]:
        if r["individual_label_in_paper"]["value"] not in ind_labels:
            problems.append("LABEL %s: %s" % (tname, r["individual_label_in_paper"]["value"]))

# checklist completeness
CHECKLIST = ["oral ulcers", "genital ulcers", "gastrointestinal ulcers or inflammation", "recurrent fever",
             "arthritis or arthralgia", "uveitis or other ocular inflammation",
             "skin lesions (rash, folliculitis, erythema nodosum)", "autoimmune thyroiditis", "type 1 diabetes",
             "autoimmune hepatitis", "cytopenia (autoimmune)", "lymphoproliferation or lymphadenopathy",
             "central nervous system involvement", "recurrent infections", "elevated inflammatory markers (CRP/ESR)",
             "autoantibodies (ANA/other)", "growth failure", "pericarditis or other serositis",
             "interstitial lung disease", "vasculitis"]
cnt = collections.Counter(r["individual_label_in_paper"]["value"] for r in data["tables"]["phenotype_checklist"])
for lab in ind_labels:
    if cnt[lab] != 20:
        problems.append("CHECKLIST count %s = %d" % (lab, cnt[lab]))
for r in data["tables"]["phenotype_checklist"]:
    if r["checklist_feature"]["value"] not in CHECKLIST:
        problems.append("CHECKLIST name: " + r["checklist_feature"]["value"])
    if r["status"]["value"] == "not reported" and r["evidence_basis"]["value"] != "not reported":
        problems.append("CHECKLIST basis: " + r["individual_label_in_paper"]["value"])

# enum values
for tname, rows in data["tables"].items():
    for f in schema["tables"]:
        if f["name"] != tname: continue
        enums = {x["name"]: x["enum_values"] for x in f["fields"] if x["enum_values"]}
    for i, row in enumerate(rows):
        for fn, ev in enums.items():
            v = row[fn]["value"]
            if v is not None and v not in ev:
                problems.append("ENUM %s[%d].%s = %r" % (tname, i, fn, v))

print("rows:", {k: len(v) for k, v in data["tables"].items()})
print("individuals:", len(ind_labels), ind_labels)
print("problems:", len(problems))
for p in problems[:60]:
    print(" -", p)
